      id: [String, Number],\r\n        name: String,\r\n        image: String,\r\n        price: [String, Number],\r\n        articule: String,\r\n        availability: {\r\n            type: Number,\r\n            default: 1\r\n        },\r\n        isWholesale: {\r\n            type: Boolean,\r\n            default: false\r\n        },\r\n        wholesalePrice: {\r\n            type: [String, Number],\r\n            default: null\r\n        },\r\n        wholesaleMinQuantity: {\r\n            type: [String, Number],\r\n            default: null\r\n        }\r\n    },\r\n    data() {\r\n        return {\r\n            inCart: false,\r\n            cartItemQuantity: 0,\r\n            productData: {\r\n                id: null,\r\n                name: '',\r\n                price: '',\r\n                image: '',\r\n                articule: '',\r\n                availability: 1,\r\n                isWholesale: false,\r\n                wholesalePrice: null,\r\n                wholesaleMinQuantity: null\r\n            }\r\n        };\r\n    },\r\n    computed: {\r\n        compactMode() {\r\n            // Проверяем, есть ли класс 'compact' у родительского элемента\r\n            return this.$el && this.$el.classList && this.$el.classList.contains('compact');\r\n        },\r\n        finalId() {\r\n            return this.productData.id || this.id;\r\n        },\r\n        finalName() {\r\n            return this.productData.name || this.name;\r\n        },\r\n        finalPrice() {\r\n            return this.productData.price || this.price;\r\n        },\r\n        finalImage() {\r\n            return this.productData.image || this.image;\r\n        },\r\n        finalArticule() {\r\n            return this.productData.articule || this.articule;\r\n        },\r\n        finalAvailability() {\r\n            return this.productData.availability || this.availability;\r\n        },\r\n        finalIsWholesale() {\r\n            return this.productData.isWholesale ||